package cn.adc.duration;
import cn.adc.shared.audit.*;import cn.adc.shared.db.JdbcTransactions;import cn.adc.shared.security.StaffAuthorization;import cn.adc.shared.time.StrictInputPolicy;import tools.jackson.databind.*;import tools.jackson.databind.node.*;import java.sql.*;import java.time.*;import java.util.*;
public final class DurationPolicyService implements DurationOperations {
 public enum ChangeKind{FIRST,PROJECT_CHANGED,TIME_ONLY,SCHEDULE_ONLY}
 public record Basis(long projectId,int versionNo,int minutes){public Basis{if(projectId<=0||versionNo<=0||minutes<=0)throw new IllegalArgumentException("BASIS_REQUIRED");}}
 public static Basis selectBasis(ChangeKind kind,Basis original,Basis current){var chosen=switch(kind){case TIME_ONLY,SCHEDULE_ONLY->original;default->current;};if(chosen==null)throw new IllegalArgumentException("BASIS_REQUIRED");return chosen;}
 private final JdbcTransactions tx;private final StaffAuthorization auth;private final Clock clock;private final DurationRepository repo=new DurationRepository();private final CommandRecovery commands;
 public DurationPolicyService(JdbcTransactions tx,StaffAuthorization auth,Clock clock){this.tx=tx;this.auth=auth;this.clock=clock;commands=new ExtensionAuditService(tx,auth,new DurationSuccessVerifier(),clock).commands();}
 public static void validateDraft(JsonNode n){String name=AuditDocuments.text(n,"projectName");if(name.codePointCount(0,name.length())>200)throw new IllegalArgumentException("NAME_TOO_LONG");StrictInputPolicy.positiveMinutes(n.get("durationMinutes"));}
 private static long id(JsonNode n,String field){try{String s=AuditDocuments.text(n,field);if(!s.matches("[1-9][0-9]*"))throw new IllegalArgumentException("INVALID_ID");return Long.parseLong(s);}catch(NumberFormatException e){throw new IllegalArgumentException("INVALID_ID");}}
 private static JsonNode required(JsonNode row){if(row==null)throw new IllegalArgumentException("VERSION_NOT_FOUND");return row;}
 private static void token(JsonNode row,String expected){if(!AuditDocuments.hash(row).equals(expected))throw new IllegalArgumentException("STALE_VERSION");}
 private static ObjectNode envelope(JsonNode target,JsonNode previous){var n=AuditDocuments.JSON.createObjectNode();n.set("targetVersion",target==null?NullNode.getInstance():target);n.set("previousCurrentVersion",previous==null?NullNode.getInstance():previous);return n;}
 private AuditDocuments.Change change(long id,int version,JsonNode before,JsonNode after,JsonNode previous,JsonNode superseded){var ref=AuditDocuments.JSON.createObjectNode().put("projectId",Long.toString(id)).put("versionNo",version);return new AuditDocuments.Change(ref,envelope(before,previous),envelope(after,superseded),AuditDocuments.JSON.createObjectNode().put("conclusion","VERIFIED").put("source","ACTUAL_LOCKED_CONFIGURATION"));}
 private CommandRecovery.Command command(String op,UUID key,JsonNode body,long id,int v){var payload=body.deepCopy();if(id>0){var p=AuditDocuments.JSON.createObjectNode().put("projectId",Long.toString(id)).put("versionNo",v);p.set("input",payload);payload=p;}return new CommandRecovery.Command(op,null,key,payload,Set.of());}
 public CommandRecovery.Receipt create(UUID key,JsonNode input){var cmd=command("DURATION_DRAFT_CREATE",key,input,0,0);return commands.execute(cmd,(c,l)->{validateDraft(input);var allowed=Set.of("projectId","expectedBaseVersion","projectName","durationMinutes");if(!input.isObject()||!allowed.containsAll(input.propertyNames()))throw new IllegalArgumentException("UNKNOWN_FIELD");long id;int version;if(input.has("projectId")){id=id(input,"projectId");int base=StrictInputPolicy.positiveMinutes(input.get("expectedBaseVersion"));required(repo.version(c,id,base));version=repo.nextVersion(c,id);}else{if(input.has("expectedBaseVersion"))throw new IllegalArgumentException("PROJECT_REQUIRED");id=repo.nextProject(c);version=1;}repo.create(c,id,version,AuditDocuments.text(input,"projectName"),StrictInputPolicy.positiveMinutes(input.get("durationMinutes")));return change(id,version,null,repo.version(c,id,version),null,null);});}
 public CommandRecovery.Receipt edit(UUID key,long id,int v,JsonNode input){return commands.execute(command("DURATION_DRAFT_EDIT",key,input,id,v),(c,l)->{validateDraft(input);if(!Set.of("projectId","expectedBaseVersion","projectName","durationMinutes","expectedStateToken","reason").containsAll(input.propertyNames()))throw new IllegalArgumentException("UNKNOWN_FIELD");if(id<=0||v<=0||input.has("projectId")&&id(input,"projectId")!=id||input.has("expectedBaseVersion")&&StrictInputPolicy.positiveMinutes(input.get("expectedBaseVersion"))!=v)throw new IllegalArgumentException("INVALID_VERSION");var before=required(repo.version(c,id,v));if(!before.path("publication_status").asText().equals("DRAFT"))throw new IllegalArgumentException("PUBLISHED_IMMUTABLE");token(before,AuditDocuments.text(input,"expectedStateToken"));AuditDocuments.text(input,"reason");repo.edit(c,id,v,AuditDocuments.text(input,"projectName"),StrictInputPolicy.positiveMinutes(input.get("durationMinutes")));return change(id,v,before,repo.version(c,id,v),null,null);});}
 private static JsonNode content(JsonNode row){if(row==null)return NullNode.getInstance();return AuditDocuments.JSON.createObjectNode().put("projectId",row.path("project_id").asText()).put("versionNo",row.path("duration_version_no").intValue()).put("projectName",row.path("project_name").asText()).put("durationMinutes",row.path("duration_minutes").intValue()).put("publicationStatus",row.path("publication_status").asText()).put("publishedAt",row.path("published_at").asText()).put("publishedBy",row.path("published_by").asText());}
 public CommandRecovery.Receipt publish(UUID key,long id,int v,JsonNode input){var cmd=command("DURATION_PUBLISH",key,input,id,v);final CommandRecovery.Ticket ticket;try{ticket=commands.begin(cmd);}catch(CommandRecovery.Unavailable e){return e.receipt();}return commands.perform(ticket,(c,l)->{AuditDocuments.fields(input,"expectedDraftToken","expectedCurrentRef","reason");if(id<=0||v<=0)throw new IllegalArgumentException("INVALID_VERSION");var before=required(repo.version(c,id,v));if(!before.path("publication_status").asText().equals("DRAFT"))throw new IllegalArgumentException("DRAFT_REQUIRED");token(before,AuditDocuments.text(input,"expectedDraftToken"));String reason=AuditDocuments.text(input,"reason");var old=repo.current(c,id);var expected=input.get("expectedCurrentRef");if(expected==null||((old==null)!=expected.isNull()))throw new IllegalArgumentException("CURRENT_CHANGED");if(old!=null&&(id(expected,"projectId")!=id||StrictInputPolicy.positiveMinutes(expected.get("versionNo"))!=old.path("duration_version_no").intValue()))throw new IllegalArgumentException("CURRENT_CHANGED");var actor=auth.require("DURATION_PUBLISH",Set.of());Instant at=StrictInputPolicy.eventTime(clock);var published=(ObjectNode)before.deepCopy();published.put("publication_status","CURRENT").put("published_at",at.toString()).put("published_by",actor.actor());var doc=AuditDocuments.JSON.createObjectNode().put("schemaVersion",1).put("operationKind","DURATION_PUBLISH").put("requestReference",ticket.requestReference()).put("canonicalPayloadHash",ticket.canonicalPayloadHash()).put("actorReference",actor.actor()).put("authorizationScope","GLOBAL_CATALOG").put("reason",reason).put("expectedDraftFingerprint",AuditDocuments.hash(before)).put("recordedAt",at.toString());if(old==null)doc.putNull("previousCurrentRef");else doc.putObject("previousCurrentRef").put("projectId",Long.toString(id)).put("versionNo",old.path("duration_version_no").intValue());doc.set("before",content(old));doc.set("after",content(published));if(old!=null)repo.supersede(c,id,old.path("duration_version_no").intValue());repo.publish(c,id,v,at,actor.actor(),doc);return change(id,v,before,repo.version(c,id,v),old,old==null?null:repo.version(c,id,old.path("duration_version_no").intValue()));});}
 private void readPermission(){var e=auth.evaluate("DURATION_EDIT",Set.of());if(!e.allowed()&&!auth.evaluate("DURATION_PUBLISH",Set.of()).allowed())throw new SecurityException("CATALOG_READ_DENIED");}
 public Map<String,Boolean> capabilities(){return Map.of("canEdit",auth.evaluate("DURATION_EDIT",Set.of()).allowed(),"canPublish",auth.evaluate("DURATION_PUBLISH",Set.of()).allowed());}
 public String requestNamespace(){readPermission();String ref=commands.reference(new CommandRecovery.Command("DURATION_DRAFT_CREATE",null,new UUID(0,0),AuditDocuments.JSON.createObjectNode(),Set.of()));return ref.substring(0,ref.lastIndexOf("/DURATION_DRAFT_CREATE/"));}
 public JsonNode version(long id,int v){readPermission();if(id<=0||v<=0)throw new IllegalArgumentException("INVALID_VERSION");return tx.execute(c->{var row=required(repo.version(c,id,v));readPermission();return row;});}
 public List<JsonNode> current(){readPermission();return tx.execute(c->{var rows=repo.current(c);readPermission();return rows;});}
 public List<JsonNode> currentPage(int limit,long after){if(limit<1||limit>100||after<0)throw new IllegalArgumentException("INVALID_PAGE");readPermission();return tx.execute(c->{var rows=repo.currentPage(c,limit,after);readPermission();return rows;});}
 public CommandRecovery.Receipt recover(String reference){return commands.recoverReference(reference);}
}
